-- Migration: thêm cột ảnh/video Lyfta cho exercises_library + gán ảnh verified.
-- Chạy trong Supabase Dashboard > SQL Editor. An toàn: chỉ ADD COLUMN IF NOT EXISTS + UPDATE.
-- Nguồn ảnh: trang exercise Lyfta thật (og:image), không đoán mò.

ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS image_url text;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS video_url text;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS secondary_muscles text;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS muscle_group text;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS primary_muscle text;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS equipment text;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS default_sets int DEFAULT 3;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS default_min_rep int DEFAULT 8;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS default_max_rep int DEFAULT 12;
ALTER TABLE exercises_library ADD COLUMN IF NOT EXISTS default_rest_seconds int DEFAULT 90;

